import assert from 'node:assert/strict';import {chromium} from 'playwright-core';
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--disable-gpu','--no-first-run']});const page=await browser.newPage({viewport:{width:1600,height:980}});const failures=[];page.on('pageerror',e=>failures.push(e.message));
try{await page.goto('http://127.0.0.1:5978/?desktop=1&engine=clothcraft&testSession=collapse-restore-both-20261028',{waitUntil:'domcontentloaded'});await page.locator('.main-layout').waitFor();const results=[];
for(const mode of ['3d','2d']){await page.getByRole('combobox',{name:'3D and 2D window arrangement'}).selectOption(mode);const root=page.locator('.main-layout');
for(const pair of [['Collapse library panel','Expand library panel','libraryVisible'],['Collapse left tools panel','Expand left tools panel','leftToolsCollapsed'],['Collapse right tools toolbar','Expand right tools toolbar','rightToolsCollapsed']]){await page.getByRole('button',{name:pair[0]}).first().click();const restore=page.getByRole('button',{name:pair[1]}).first();await restore.waitFor({state:'visible'});const box=await restore.boundingBox();assert(box&&box.width>=15&&box.height>=15);await restore.click();results.push(`${mode}:${pair[2]}:restored`)}
await page.evaluate(()=>{const node=document.querySelector('.main-layout .exo-object-inspector-header-arrow');if(node)node.click();else document.querySelector('[aria-label="Show or hide Property Editor"]')?.click()});const reopen=page.getByRole('button',{name:'Expand Object Browser and Property Editor panel'}).first();await reopen.waitFor({state:'visible'});await reopen.click();results.push(`${mode}:inspector:restored`)}
assert.equal(failures.length,0,failures.join('; '));console.log(JSON.stringify({ok:true,results},null,2))}finally{await browser.close()}
